        let mut buf = CodeBuffer::new();
        {
            let mut emit = X86Emitter::new(&mut buf);
            emit.emit_mov_ri(PhysReg::Rax, 42, OpWidth::W64);
        }
        // MOV RAX, 42 (using imm32 sign-extended)
