    #[test]
    fn lower_cwd_cdq_cqo_emits_exact_encodings_and_rejects_malformed_shapes() {
        let gpr = |reg| VReg::Arch(ArchReg::X86(reg));

        for (name, width, expected) in [
            ("CWD", OpWidth::W16, &[0x66, 0x99][..]),
            ("CDQ", OpWidth::W32, &[0x99][..]),
            ("CQO", OpWidth::W64, &[0x48, 0x99][..]),
        ] {
            let code = lower_single_op(OpKind::Cwd {
                dst: gpr(X86Reg::Rdx),
                src: gpr(X86Reg::Rax),
                width,
            });
            assert!(
                code.windows(expected.len()).any(|bytes| bytes == expected),
                "{name}: missing {expected:02X?} in {code:02X?}"
            );
        }

        for (name, op) in [
            (
                "wrong source",
                OpKind::Cwd {
                    dst: gpr(X86Reg::Rdx),
                    src: gpr(X86Reg::Rcx),
                    width: OpWidth::W64,
                },
            ),
            (
                "wrong destination",
                OpKind::Cwd {
                    dst: gpr(X86Reg::Rcx),
                    src: gpr(X86Reg::Rax),
                    width: OpWidth::W32,
                },
            ),
            (
                "unsupported width",
                OpKind::Cwd {
                    dst: gpr(X86Reg::Rdx),
                    src: gpr(X86Reg::Rax),
                    width: OpWidth::W8,
                },
            ),
        ] {
            assert!(
                matches!(
                    lower_single_op_err(op),
                    LowerError::InvalidOperand { .. } | LowerError::UnsupportedOp { .. }
                ),
                "{name}"
            );
        }
    }

    #[test]
    fn lower_mulx_hint_emits_native_bmi2_with_aliasing() {
        let gpr = |reg| VReg::Arch(ArchReg::X86(reg));

        for (name, dst_lo, dst_hi, src2, width, expected) in [
            (
                "64-bit",
                X86Reg::Rbx,
                X86Reg::Rcx,
                X86Reg::Rax,
                OpWidth::W64,
                &[0xC4, 0xE2, 0xE3, 0xF6, 0xC8][..],
            ),
            (
                "32-bit extended",
                X86Reg::R8,
                X86Reg::R9,
                X86Reg::R10,
                OpWidth::W32,
                &[0xC4, 0x42, 0x3B, 0xF6, 0xCA][..],
            ),
            (
                "same destination keeps upper half",
                X86Reg::Rcx,
                X86Reg::Rcx,
                X86Reg::Rax,
                OpWidth::W64,
                &[0xC4, 0xE2, 0xF3, 0xF6, 0xC8][..],
            ),
        ] {
            let mut builder = FunctionBuilder::new(FunctionId(0), 0x1000);
            builder.push_op(
                0x1000,
                OpKind::MulU {
                    dst_lo: gpr(dst_lo),
                    dst_hi: Some(gpr(dst_hi)),
                    src1: gpr(X86Reg::Rdx),
                    src2: SrcOperand::Reg(gpr(src2)),
                    width,
                    flags: FlagUpdate::None,
                },
            );
            builder.set_terminator(Terminator::Return { values: vec![] });
            let mut func = builder.finish();
            func.blocks[0].ops[0].x86_hint = Some(X86OpHint::Mulx);

            let mut lowerer = X86_64Lowerer::new();
            let result = lowerer.lower_function(&func).expect(name);
            assert!(result.relocations.is_empty(), "{name}");
            let code = lowerer.finalize().expect(name);
            assert!(
                code.windows(expected.len())
                    .any(|window| window == expected),
                "{name}: missing MULX {expected:02X?} in {code:02X?}"
            );
        }
    }

