    #[test]
    fn lower_register_bit_tests_emit_all_widths_and_reject_malformed_shapes() {
        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let rcx = VReg::Arch(ArchReg::X86(X86Reg::Rcx));
        let r8 = VReg::Arch(ArchReg::X86(X86Reg::R8));
        let r9 = VReg::Arch(ArchReg::X86(X86Reg::R9));
        let r10 = VReg::Arch(ArchReg::X86(X86Reg::R10));

        let bt = lower_single_op(OpKind::Bt {
            src: rax,
            index: SrcOperand::Reg(rcx),
            width: OpWidth::W32,
        });
        assert!(
            bt.windows(4).any(|bytes| bytes == [0x9C, 0x0F, 0xA3, 0xC8]),
            "missing BT r32,r32 encoding: {bt:02X?}"
        );

        let btr = lower_single_op(OpKind::Btr {
            dst: r8,
            src: r8,
            index: SrcOperand::Imm(31),
            width: OpWidth::W32,
        });
        assert!(
            btr.windows(6)
                .any(|bytes| bytes == [0x9C, 0x41, 0x0F, 0xBA, 0xF0, 0x1F]),
            "missing BTR r32,imm8 encoding: {btr:02X?}"
        );

        let btc = lower_single_op(OpKind::Btc {
            dst: r9,
            src: r9,
            index: SrcOperand::Reg(r10),
            width: OpWidth::W16,
        });
        assert!(
            btc.windows(6)
                .any(|bytes| bytes == [0x9C, 0x66, 0x45, 0x0F, 0xBB, 0xD1]),
            "missing BTC r16,r16 encoding: {btc:02X?}"
        );

        for malformed in [
            OpKind::Bts {
                dst: rax,
                src: rcx,
                index: SrcOperand::Imm(1),
                width: OpWidth::W64,
            },
            OpKind::Bt {
                src: rax,
                index: SrcOperand::Imm(1),
                width: OpWidth::W8,
            },
            OpKind::Bt {
                src: VReg::Arch(ArchReg::X86(X86Reg::Rsp)),
                index: SrcOperand::Imm(1),
                width: OpWidth::W64,
            },
        ] {
            assert!(
                matches!(
                    lower_single_op_err(malformed),
                    LowerError::InvalidOperand { .. }
                        | LowerError::InvalidRegister(_)
                        | LowerError::RegisterAllocationFailed { .. }
                ),
                "malformed register bit test must fail lowering"
            );
        }
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_register_bit_tests_preserve_undefined_flags_and_partial_writes() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        let r8 = VReg::Arch(ArchReg::X86(X86Reg::R8));
        let r9 = VReg::Arch(ArchReg::X86(X86Reg::R9));
        const STATUS: u64 = 0x8D5; // CF, PF, AF, ZF, SF, OF
        let cases = [
            (
                "bt r64,r64",
                OpKind::Bt {
                    src: r8,
                    index: SrcOperand::Reg(r9),
                    width: OpWidth::W64,
                },
                1u64 << 63,
                63,
                1u64 << 63,
                true,
            ),
            (
                "bts r16,imm8",
                OpKind::Bts {
                    dst: r8,
                    src: r8,
                    index: SrcOperand::Imm(15),
                    width: OpWidth::W16,
                },
                0xA5A5_A5A5_A5A5_0000,
                0,
                0xA5A5_A5A5_A5A5_8000,
                false,
            ),
            (
                "btr r32,imm8",
                OpKind::Btr {
                    dst: r8,
                    src: r8,
                    index: SrcOperand::Imm64(31),
                    width: OpWidth::W32,
                },
                u64::MAX,
                0,
                0x7FFF_FFFF,
                true,
            ),
            (
                "btc r64,r64",
                OpKind::Btc {
                    dst: r8,
                    src: r8,
                    index: SrcOperand::Reg(r9),
                    width: OpWidth::W64,
                },
                0,
                63,
                1u64 << 63,
                false,
            ),
        ];

        for (name, kind, source, index, expected, expected_cf) in cases {
            let mut builder = FunctionBuilder::new(FunctionId(0), 0x1000);
            builder.push_op(0x1000, kind);
            builder.set_terminator(Terminator::Return { values: vec![] });
            let mut lowerer = X86_64Lowerer::new();
            let lowered = lowerer
                .lower_function(&builder.finish())
                .unwrap_or_else(|error| panic!("lower {name}: {error:?}"));
            let code = lowerer.finalize().expect("finalize register bit test");
            let exec = ExecMem::new(&code).expect("map register bit test");
            let mut regs = GuestRegs::default();
            regs.gpr[8] = source;
            regs.gpr[9] = index;
            regs.rflags = 0x2 | STATUS;
            exec.run(lowered.entry_offset, &mut regs);

            assert_eq!(regs.gpr[8], expected, "{name}: result");
            let expected_status = (STATUS & !1) | u64::from(expected_cf);
            assert_eq!(
                regs.rflags & STATUS,
                expected_status,
                "{name}: only CF may change"
            );
        }
    }

    #[test]
    fn lower_crc32c_emits_every_source_width_and_rejects_malformed_shapes() {
        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let rsi = VReg::Arch(ArchReg::X86(X86Reg::Rsi));
        let r8 = VReg::Arch(ArchReg::X86(X86Reg::R8));
        let r9 = VReg::Arch(ArchReg::X86(X86Reg::R9));
        let r10 = VReg::Arch(ArchReg::X86(X86Reg::R10));
        let r11 = VReg::Arch(ArchReg::X86(X86Reg::R11));
        let r12 = VReg::Arch(ArchReg::X86(X86Reg::R12));
        let r13 = VReg::Arch(ArchReg::X86(X86Reg::R13));

        for (name, op, expected) in [
            (
                "crc32 r32,r8",
                OpKind::Crc32C {
                    dst: rax,
                    crc: rax,
                    data: rsi,
                    data_width: OpWidth::W8,
                },
                &[0xF2, 0x40, 0x0F, 0x38, 0xF0, 0xC6][..],
            ),
            (
                "crc32 r32,r16",
                OpKind::Crc32C {
                    dst: r8,
                    crc: r8,
                    data: r9,
                    data_width: OpWidth::W16,
                },
                &[0xF2, 0x66, 0x45, 0x0F, 0x38, 0xF1, 0xC1][..],
            ),
            (
                "crc32 r32,r32",
                OpKind::Crc32C {
                    dst: r10,
                    crc: r10,
                    data: r11,
                    data_width: OpWidth::W32,
                },
                &[0xF2, 0x45, 0x0F, 0x38, 0xF1, 0xD3][..],
            ),
            (
                "crc32 r64,r64",
                OpKind::Crc32C {
                    dst: r12,
                    crc: r12,
                    data: r13,
                    data_width: OpWidth::W64,
                },
                &[0xF2, 0x4D, 0x0F, 0x38, 0xF1, 0xE5][..],
            ),
        ] {
            let code = lower_single_op(op);
            assert!(
                code.windows(expected.len()).any(|bytes| bytes == expected),
                "{name}: missing {expected:02X?} in {code:02X?}"
            );
        }

        for malformed in [
            OpKind::Crc32C {
                dst: r8,
                crc: r9,
                data: r10,
                data_width: OpWidth::W64,
            },
            OpKind::Crc32C {
                dst: r8,
                crc: r8,
                data: r9,
                data_width: OpWidth::W128,
            },
            OpKind::Crc32C {
                dst: VReg::Arch(ArchReg::X86(X86Reg::Rsp)),
                crc: VReg::Arch(ArchReg::X86(X86Reg::Rsp)),
                data: r9,
                data_width: OpWidth::W32,
            },
            OpKind::Crc32C {
                dst: r8,
                crc: r8,
                data: VReg::Virtual(crate::smir::ir::types::VirtualId(99)),
                data_width: OpWidth::W16,
            },
        ] {
            let error = lower_single_op_err(malformed);
            assert!(
                matches!(
                    error,
                    LowerError::InvalidRegister(_)
                        | LowerError::RegisterAllocationFailed { .. }
                        | LowerError::InvalidOperand { .. }
                        | LowerError::UnsupportedOp { .. }
                ),
                "malformed CRC32 must fail lowering"
            );
        }
    }

