    #[test]
    fn lower_x86_alignment_check_emits_precise_deopt_and_rejects_malformed_ir() {
        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let code = lower_single_op(OpKind::X86CheckAlignment {
            addr: Address::Direct(rax),
            alignment: 64,
        });
        assert!(
            code.windows(7)
                .any(|bytes| bytes == [0x48, 0xF7, 0xC6, 0x3F, 0, 0, 0]),
            "alignment mask test missing from {code:02X?}"
        );
        assert!(
            code.windows(2).any(|bytes| bytes == [0x0F, 0x85]),
            "misalignment must branch to the current-PC exit"
        );

        for malformed in [
            OpKind::X86CheckAlignment {
                addr: Address::Direct(rax),
                alignment: 8,
            },
            OpKind::X86CheckAlignment {
                addr: Address::Direct(VReg::Virtual(crate::smir::ir::types::VirtualId(7))),
                alignment: 16,
            },
            OpKind::X86CheckAlignment {
                addr: Address::BaseIndexScale {
                    base: None,
                    index: rax,
                    scale: 3,
                    disp: 0,
                    disp_size: DispSize::Auto,
                },
                alignment: 32,
            },
            OpKind::X86CheckAlignment {
                addr: Address::PcRel {
                    offset: 0,
                    disp_size: DispSize::Auto,
                    base: None,
                },
                alignment: 64,
            },
            OpKind::X86CheckAlignment {
                addr: Address::GpRel { offset: 0 },
                alignment: 16,
            },
        ] {
            assert!(
                matches!(
                    lower_single_op_err(malformed),
                    LowerError::InvalidOperand { .. }
                        | LowerError::UnsupportedOp { .. }
                        | LowerError::InvalidRegister(_)
                        | LowerError::RegisterAllocationFailed { .. }
                ),
                "malformed alignment check must fail lowering"
            );
        }
    }

    #[test]
    fn lower_helper_backed_vector_memory_uses_state_abi_and_rejects_malformed_ir() {
        let x86 = |reg| VReg::Arch(ArchReg::X86(reg));
        let lower = |kind: OpKind, hint: Option<X86OpHint>| -> Result<Vec<u8>, LowerError> {
            let mut builder = FunctionBuilder::new(FunctionId(0), 0x1000);
            builder.push_op(0x1000, kind);
            builder.set_terminator(Terminator::Return { values: vec![] });
            let mut function = builder.finish();
            function.blocks[0].ops[0].x86_hint = hint;
            let mut lowerer = X86_64Lowerer::new();
            lowerer.set_mem_helpers(true);
            lowerer.lower_function(&function)?;
            lowerer.finalize()
        };

        let load = lower(
            OpKind::VLoad {
                dst: x86(X86Reg::Ymm(17)),
                addr: Address::BaseOffset {
                    base: x86(X86Reg::Rsp),
                    offset: 32,
                    disp_size: DispSize::Disp8,
                },
                width: VecWidth::V256,
            },
            Some(X86OpHint::VexOp {
                map: X86VecMap::Map0F,
                pp: X86SsePrefix::Rep,
                opcode: 0x6F,
                width: VecWidth::V256,
                w: false,
            }),
        )
        .expect("lower helper-backed YMM load");
        let mut load_call = vec![0xFF, 0x90];
        load_call.extend_from_slice(&(X86_GUEST_VEC_LOAD_FN_OFFSET as u32).to_le_bytes());
        assert!(
            load.windows(load_call.len())
                .any(|bytes| bytes == load_call)
        );
        assert!(
            load.windows(6)
                .any(|bytes| bytes == [0x41, 0xB8, 1, 0, 0, 0]),
            "VEX load must request upper-lane zeroing: {load:02X?}"
        );

        let legacy = lower(
            OpKind::VLoad {
                dst: x86(X86Reg::Xmm(3)),
                addr: Address::Absolute(0x2000),
                width: VecWidth::V128,
            },
            Some(X86OpHint::SseMov {
                prefix: X86SsePrefix::OpSize,
                opcode: 0x6F,
            }),
        )
        .expect("lower helper-backed legacy XMM load");
        assert!(
            legacy
                .windows(6)
                .any(|bytes| bytes == [0x41, 0xB8, 0, 0, 0, 0]),
            "legacy SSE load must preserve upper lanes: {legacy:02X?}"
        );

        let store = lower(
            OpKind::VStore {
                src: x86(X86Reg::Zmm(31)),
                addr: Address::SegmentRel {
                    segment: x86(X86Reg::GsBase),
                    base: Some(x86(X86Reg::Rbp)),
                    index: Some(x86(X86Reg::R16)),
                    scale: 4,
                    disp: i64::MAX,
                },
                width: VecWidth::V512,
            },
            None,
        )
        .expect("lower helper-backed ZMM store");
        let mut store_call = vec![0xFF, 0x90];
        store_call.extend_from_slice(&(X86_GUEST_VEC_STORE_FN_OFFSET as u32).to_le_bytes());
        assert!(
            store
                .windows(store_call.len())
                .any(|bytes| bytes == store_call)
        );

        for malformed in [
            OpKind::VLoad {
                dst: x86(X86Reg::Xmm(0)),
                addr: Address::Direct(x86(X86Reg::Rax)),
                width: VecWidth::V256,
            },
            OpKind::VStore {
                src: VReg::Virtual(crate::smir::ir::types::VirtualId(7)),
                addr: Address::Direct(x86(X86Reg::Rax)),
                width: VecWidth::V128,
            },
            OpKind::VLoad {
                dst: x86(X86Reg::Xmm(0)),
                addr: Address::GpRel { offset: 0 },
                width: VecWidth::V128,
            },
        ] {
            assert!(
                matches!(
                    lower(malformed, None),
                    Err(LowerError::InvalidOperand { .. }
                        | LowerError::UnsupportedOp { .. }
                        | LowerError::InvalidRegister(_)
                        | LowerError::RegisterAllocationFailed { .. })
                ),
                "malformed vector-memory IR must fail lowering"
            );
        }
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_x86_alignment_check_covers_addresses_preserves_state_and_deopts_precisely() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        let x86 = |reg| VReg::Arch(ArchReg::X86(reg));
        let marker = 0xD1CE_BA5E_F00D_CAFEu64;
        let sentinel_pc = 0xABCD_EF01_2345_6789u64;
        let status = 0x8D5u64; // CF, PF, AF, ZF, SF, OF

        let mut cases = Vec::new();

        let mut direct = GuestRegs::default();
        direct.gpr[0] = 0x1000;
        cases.push((
            "direct/aligned16",
            Address::Direct(x86(X86Reg::Rax)),
            16,
            direct,
            false,
        ));

        let mut stack = GuestRegs::default();
        stack.gpr[4] = 0x2011;
        cases.push((
            "rsp+disp/misaligned32",
            Address::BaseOffset {
                base: x86(X86Reg::Rsp),
                offset: -16,
                disp_size: DispSize::Disp8,
            },
            32,
            stack,
            true,
        ));

        let mut sib = GuestRegs::default();
        sib.gpr[5] = 0x3000;
        sib.gpr[9] = 8;
        cases.push((
            "rbp+r9*8-64/aligned64",
            Address::BaseIndexScale {
                base: Some(x86(X86Reg::Rbp)),
                index: x86(X86Reg::R9),
                scale: 8,
                disp: -64,
                disp_size: DispSize::Disp8,
            },
            64,
            sib,
            false,
        ));

        cases.push((
            "pcrel/misaligned64",
            Address::PcRel {
                offset: -1,
                disp_size: DispSize::Disp8,
                base: Some(0x4000),
            },
            64,
            GuestRegs::default(),
            true,
        ));
        cases.push((
            "absolute/aligned32",
            Address::Absolute(0x5000),
            32,
            GuestRegs::default(),
            false,
        ));

        let mut segmented = GuestRegs::default();
        segmented.fs_base = 0x5F00;
        segmented.gpr[4] = 0x80;
        segmented.gpr[16] = 0x20;
        cases.push((
            "fs+rsp+r16*4/aligned64",
            Address::SegmentRel {
                segment: x86(X86Reg::FsBase),
                base: Some(x86(X86Reg::Rsp)),
                index: Some(x86(X86Reg::R16)),
                scale: 4,
                disp: 0,
            },
            64,
            segmented,
            false,
        ));

        let mut wide_disp = GuestRegs::default();
        wide_disp.gs_base = 0x8000_0000_0000_6001;
        cases.push((
            "gs+wide-disp/aligned16",
            Address::SegmentRel {
                segment: x86(X86Reg::GsBase),
                base: None,
                index: None,
                scale: 1,
                disp: i64::MIN,
            },
            16,
            wide_disp,
            true,
        ));

        for (name, addr, alignment, mut regs, should_fault) in cases {
            let mut builder = FunctionBuilder::new(FunctionId(0), 0x1000);
            builder.push_op(0x1000, OpKind::X86CheckAlignment { addr, alignment });
            builder.push_op(
                0x1001,
                OpKind::Mov {
                    dst: x86(X86Reg::R11),
                    src: SrcOperand::Imm64(marker as i64),
                    width: OpWidth::W64,
                },
            );
            builder.set_terminator(Terminator::Return { values: vec![] });
            let mut lowerer = X86_64Lowerer::new();
            let lowered = lowerer
                .lower_function(&builder.finish())
                .unwrap_or_else(|error| panic!("lower {name}: {error:?}"));
            let exec = ExecMem::new(&lowerer.finalize().expect("finalize alignment check"))
                .expect("map alignment check");

            regs.gpr[11] = 0x1111_2222_3333_4444;
            regs.rflags = 0x2 | status;
            regs.exit_pc = sentinel_pc;
            let before = regs;
            exec.run(lowered.entry_offset, &mut regs);

            assert_eq!(regs.rflags & status, status, "{name}: status flags");
            for index in 0..32 {
                let expected = if index == 11 && !should_fault {
                    marker
                } else {
                    before.gpr[index]
                };
                assert_eq!(regs.gpr[index], expected, "{name}: gpr[{index}]");
            }
            assert_eq!(
                regs.exit_pc,
                if should_fault { 0x1000 } else { sentinel_pc },
                "{name}: precise resume PC"
            );
        }
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_x86_alignment_check_snapshots_prior_native_register_writes() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let r11 = VReg::Arch(ArchReg::X86(X86Reg::R11));
        let mut builder = FunctionBuilder::new(FunctionId(0), 0x2000);
        builder.push_op(
            0x2000,
            OpKind::Mov {
                dst: rax,
                src: SrcOperand::Imm64(0x4000),
                width: OpWidth::W64,
            },
        );
        builder.push_op(
            0x2001,
            OpKind::X86CheckAlignment {
                addr: Address::Direct(rax),
                alignment: 64,
            },
        );
        builder.push_op(
            0x2002,
            OpKind::Mov {
                dst: r11,
                src: SrcOperand::Imm(1),
                width: OpWidth::W64,
            },
        );
        builder.set_terminator(Terminator::Return { values: vec![] });
        let mut lowerer = X86_64Lowerer::new();
        let lowered = lowerer
            .lower_function(&builder.finish())
            .expect("lower prior-write alignment check");
        let exec = ExecMem::new(
            &lowerer
                .finalize()
                .expect("finalize prior-write alignment check"),
        )
        .expect("map prior-write alignment check");
        let mut regs = GuestRegs::default();
        regs.gpr[0] = 0x4001; // stale entry value is intentionally misaligned
        regs.exit_pc = 0xDEAD;
        exec.run(lowered.entry_offset, &mut regs);
        assert_eq!(regs.gpr[0], 0x4000);
        assert_eq!(regs.gpr[11], 1, "aligned continuation must execute");
        assert_eq!(regs.exit_pc, 0xDEAD, "must not deopt from stale state");
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_x86_random_preserves_width_semantics_and_defines_exact_status_flags() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        const STATUS: u64 = (1 << 0) | (1 << 2) | (1 << 4) | (1 << 6) | (1 << 7) | (1 << 11);
        const NON_CF_STATUS: u64 = STATUS & !(1 << 0);
        let r9 = VReg::Arch(ArchReg::X86(X86Reg::R9));
        for seed in [false, true] {
            if (seed && !std::is_x86_feature_detected!("rdseed"))
                || (!seed && !std::is_x86_feature_detected!("rdrand"))
            {
                continue;
            }
            for width in [OpWidth::W16, OpWidth::W32, OpWidth::W64] {
                let mut builder = FunctionBuilder::new(FunctionId(0), 0x1000);
                builder.push_op(
                    0x1000,
                    OpKind::X86Random {
                        dst: r9,
                        width,
                        seed,
                    },
                );
                builder.set_terminator(Terminator::Return { values: vec![] });
                let mut lowerer = X86_64Lowerer::new();
                let lowered = lowerer
                    .lower_function(&builder.finish())
                    .expect("lower native X86Random");
                let exec = ExecMem::new(&lowerer.finalize().expect("finalize native X86Random"))
                    .expect("map native X86Random");
                let input = 0xA5A5_5A5A_C3C3_3C3C;
                let mut regs = GuestRegs::default();
                regs.gpr[9] = input;
                regs.rflags = 0x2 | STATUS;
                exec.run(lowered.entry_offset, &mut regs);

                let success = regs.rflags & 1 != 0;
                assert_eq!(regs.rflags & NON_CF_STATUS, 0, "seed={seed} {width:?}");
                assert_ne!(regs.rflags & 0x2, 0, "reserved RFLAGS bit must survive");
                match width {
                    OpWidth::W16 => {
                        assert_eq!(regs.gpr[9] >> 16, input >> 16);
                        if !success {
                            assert_eq!(regs.gpr[9] & 0xFFFF, 0);
                        }
                    }
                    OpWidth::W32 => {
                        assert_eq!(regs.gpr[9] >> 32, 0);
                        if !success {
                            assert_eq!(regs.gpr[9], 0);
                        }
                    }
                    OpWidth::W64 => {
                        if !success {
                            assert_eq!(regs.gpr[9], 0);
                        }
                    }
                    _ => unreachable!(),
                }
            }
        }
    }

    #[test]
    fn lower_rdpid_reads_guest_tsc_aux_and_rejects_frame_registers() {
        let r9 = VReg::Arch(ArchReg::X86(X86Reg::R9));
        let code = lower_single_op(OpKind::X86ReadPid { dst: r9 });
        let expected = [
            0x4C, 0x8B, 0x4D, 0x18, // mov r9,[rbp+24] (GuestRegs pointer)
            0x45, 0x8B, 0x89, 0x90, 0x09, 0x00, 0x00, // mov r9d,[r9+2448]
        ];
        assert!(
            code.windows(expected.len()).any(|bytes| bytes == expected),
            "RDPID state load missing {expected:02X?} in {code:02X?}"
        );

        let r16 = VReg::Arch(ArchReg::X86(X86Reg::R16));
        let egpr_code = lower_single_op(OpKind::X86ReadPid { dst: r16 });
        let r16_slot = (16u32 * 8).to_le_bytes();
        assert!(
            egpr_code
                .windows(r16_slot.len())
                .any(|bytes| bytes == r16_slot),
            "APX RDPID must address GuestRegs.gpr[16]"
        );

        for dst in [
            VReg::Arch(ArchReg::X86(X86Reg::Rsp)),
            VReg::Arch(ArchReg::X86(X86Reg::Rbp)),
            VReg::Virtual(crate::smir::ir::types::VirtualId(99)),
        ] {
            assert!(
                matches!(
                    lower_single_op_err(OpKind::X86ReadPid { dst }),
                    LowerError::InvalidRegister(_)
                        | LowerError::RegisterAllocationFailed { .. }
                        | LowerError::InvalidOperand { .. }
                ),
                "malformed RDPID destination must fail lowering: {dst:?}"
            );
        }
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_rdpid_returns_emulated_tsc_aux_and_preserves_flags() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        let r9 = VReg::Arch(ArchReg::X86(X86Reg::R9));
        let mut builder = FunctionBuilder::new(FunctionId(0), 0x1000);
        builder.push_op(0x1000, OpKind::X86ReadPid { dst: r9 });
        builder.set_terminator(Terminator::Return { values: vec![] });
        let mut lowerer = X86_64Lowerer::new();
        let lowered = lowerer
            .lower_function(&builder.finish())
            .expect("lower state-backed RDPID");
        let code = lowerer.finalize().expect("finalize state-backed RDPID");
        let exec = ExecMem::new(&code).expect("map state-backed RDPID");
        let mut regs = GuestRegs::default();
        regs.gpr[9] = u64::MAX;
        regs.rflags = 0x2 | 0x8D5;
        regs.tsc_aux = 0xA5C3_7E91;
        exec.run(lowered.entry_offset, &mut regs);

        assert_eq!(regs.gpr[9], 0xA5C3_7E91, "RDPID zero-extends TSC_AUX");
        assert_eq!(regs.rflags & 0x8D5, 0x8D5, "RDPID preserves RFLAGS");

        let r16 = VReg::Arch(ArchReg::X86(X86Reg::R16));
        let mut builder = FunctionBuilder::new(FunctionId(1), 0x2000);
        builder.push_op(0x2000, OpKind::X86ReadPid { dst: r16 });
        builder.set_terminator(Terminator::Return { values: vec![] });
        let mut lowerer = X86_64Lowerer::new();
        let lowered = lowerer
            .lower_function(&builder.finish())
            .expect("lower state-backed APX RDPID");
        let exec = ExecMem::new(&lowerer.finalize().expect("finalize APX RDPID"))
            .expect("map state-backed APX RDPID");
        let mut regs = GuestRegs::default();
        regs.gpr[0] = 0x1111_2222_3333_4444;
        regs.gpr[1] = 0x5555_6666_7777_8888;
        regs.gpr[16] = u64::MAX;
        regs.rflags = 0x2 | 0x8D5;
        regs.tsc_aux = 0xA5C3_7E91;
        exec.run(lowered.entry_offset, &mut regs);
        assert_eq!(regs.gpr[16], 0xA5C3_7E91);
        assert_eq!(regs.gpr[0], 0x1111_2222_3333_4444);
        assert_eq!(regs.gpr[1], 0x5555_6666_7777_8888);
        assert_eq!(regs.rflags & 0x8D5, 0x8D5);
    }

    #[test]
    fn lower_xgetbv_requires_architectural_implicit_registers() {
        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let rcx = VReg::Arch(ArchReg::X86(X86Reg::Rcx));
        let rdx = VReg::Arch(ArchReg::X86(X86Reg::Rdx));
        let code = lower_single_op(OpKind::X86XGetBv {
            dst_low: rax,
            dst_high: rdx,
            selector: rcx,
        });
        let xcr0_offset = (X86_GUEST_XCR0_OFFSET as u32).to_le_bytes();
        let xgetbv1_offset = (X86_GUEST_XGETBV1_OFFSET as u32).to_le_bytes();
        assert!(
            code.windows(4).any(|bytes| bytes == xcr0_offset),
            "XGETBV must read the state-backed XCR0 slot"
        );
        assert!(
            code.windows(4).any(|bytes| bytes == xgetbv1_offset),
            "XGETBV(1) must read the state-backed XINUSE slot"
        );

        for malformed in [
            OpKind::X86XGetBv {
                dst_low: VReg::Arch(ArchReg::X86(X86Reg::R8)),
                dst_high: rdx,
                selector: rcx,
            },
            OpKind::X86XGetBv {
                dst_low: rax,
                dst_high: VReg::Arch(ArchReg::X86(X86Reg::R9)),
                selector: rcx,
            },
            OpKind::X86XGetBv {
                dst_low: rax,
                dst_high: rdx,
                selector: VReg::Arch(ArchReg::X86(X86Reg::R10)),
            },
        ] {
            assert!(matches!(
                lower_single_op_err(malformed),
                LowerError::InvalidOperand { .. }
            ));
        }
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_xgetbv_selects_guest_state_and_deopts_faults_precisely() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let rcx = VReg::Arch(ArchReg::X86(X86Reg::Rcx));
        let rdx = VReg::Arch(ArchReg::X86(X86Reg::Rdx));
        let mut builder = FunctionBuilder::new(FunctionId(0), 0x1234_5678);
        builder.push_op(
            0x1234_5678,
            OpKind::X86XGetBv {
                dst_low: rax,
                dst_high: rdx,
                selector: rcx,
            },
        );
        builder.set_terminator(Terminator::Return { values: vec![] });
        let mut lowerer = X86_64Lowerer::new();
        let lowered = lowerer
            .lower_function(&builder.finish())
            .expect("lower state-backed XGETBV");
        let exec = ExecMem::new(&lowerer.finalize().expect("finalize state-backed XGETBV"))
            .expect("map state-backed XGETBV");

        let flags = 0x2 | 0x8D5;
        let mut regs = GuestRegs::default();
        regs.cr4 = 1 << 18;
        regs.xcr0 = 0xFEDC_BA98_7654_3217;
        regs.xgetbv1 = 0x00F0_00F0_FFFF_00F5;
        regs.gpr[0] = u64::MAX;
        regs.gpr[1] = 0;
        regs.gpr[2] = u64::MAX;
        regs.rflags = flags;
        regs.exit_pc = 0xAAAA_BBBB_CCCC_DDDD;
        exec.run(lowered.entry_offset, &mut regs);
        assert_eq!(regs.gpr[0], 0x7654_3217);
        assert_eq!(regs.gpr[2], 0xFEDC_BA98);
        assert_eq!(regs.gpr[1], 0, "XGETBV preserves RCX");
        assert_eq!(regs.rflags & 0x8D5, flags & 0x8D5);
        assert_eq!(regs.exit_pc, 0xAAAA_BBBB_CCCC_DDDD);

        regs.gpr[0] = u64::MAX;
        regs.gpr[1] = 1;
        regs.gpr[2] = u64::MAX;
        regs.rflags = flags;
        exec.run(lowered.entry_offset, &mut regs);
        let xinuse = regs.xgetbv1 & regs.xcr0;
        assert_eq!(regs.gpr[0], xinuse as u32 as u64);
        assert_eq!(regs.gpr[2], (xinuse >> 32) as u32 as u64);
        assert_eq!(regs.gpr[1], 1);
        assert_eq!(regs.rflags & 0x8D5, flags & 0x8D5);

        for (name, cr4, selector) in [
            ("OSXSAVE clear", 0, 0),
            ("invalid selector", 1 << 18, 2),
            ("large low-32 selector", 1 << 18, 0xFFFF_FFFF),
        ] {
            let mut fault = GuestRegs::default();
            fault.cr4 = cr4;
            fault.xcr0 = regs.xcr0;
            fault.xgetbv1 = regs.xgetbv1;
            fault.gpr[0] = 0x1111_2222_3333_4444;
            fault.gpr[1] = selector;
            fault.gpr[2] = 0x5555_6666_7777_8888;
            fault.rflags = flags;
            fault.exit_pc = 0;
            exec.run(lowered.entry_offset, &mut fault);
            assert_eq!(fault.exit_pc, 0x1234_5678, "{name}: precise restart PC");
            assert_eq!(fault.gpr[0], 0x1111_2222_3333_4444, "{name}: RAX");
            assert_eq!(fault.gpr[1], selector, "{name}: RCX");
            assert_eq!(fault.gpr[2], 0x5555_6666_7777_8888, "{name}: RDX");
            assert_eq!(fault.rflags & 0x8D5, flags & 0x8D5, "{name}: flags");
        }
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_xsetbv_validates_state_commits_and_hands_off_precisely() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        let rax = VReg::Arch(ArchReg::X86(X86Reg::Rax));
        let rcx = VReg::Arch(ArchReg::X86(X86Reg::Rcx));
        let rdx = VReg::Arch(ArchReg::X86(X86Reg::Rdx));
        let mut builder = FunctionBuilder::new(FunctionId(0), 0x1234_5000);
        builder.push_op(
            0x1234_5000,
            OpKind::X86XSetBv {
                selector: rcx,
                src_low: rax,
                src_high: rdx,
            },
        );
        builder.push_op(0x1234_5003, OpKind::Nop);
        builder.set_terminator(Terminator::Return { values: vec![] });
        let mut lowerer = X86_64Lowerer::new();
        let lowered = lowerer
            .lower_function(&builder.finish())
            .expect("lower state-backed XSETBV");
        let exec = ExecMem::new(&lowerer.finalize().expect("finalize state-backed XSETBV"))
            .expect("map state-backed XSETBV");

        let flags = 0x2 | 0x8D5;
        let run = |value: u64, cr4: u64, cr0: u64, cpl: u64, apx_enabled: bool, selector: u32| {
            let mut regs = GuestRegs::default();
            regs.cr4 = cr4;
            regs.cr0 = cr0;
            regs.cpl = cpl;
            regs.apx_enabled = u64::from(apx_enabled);
            regs.xcr0 = 3;
            regs.gpr[0] = 0xA5A5_A5A5_0000_0000 | (value as u32 as u64);
            regs.gpr[1] = 0x5A5A_5A5A_0000_0000 | u64::from(selector);
            regs.gpr[2] = 0xC3C3_C3C3_0000_0000 | ((value >> 32) as u32 as u64);
            regs.rflags = flags;
            regs.exit_pc = 0;
            let inputs = (regs.gpr[0], regs.gpr[1], regs.gpr[2]);
            exec.run(lowered.entry_offset, &mut regs);
            assert_eq!(
                (regs.gpr[0], regs.gpr[1], regs.gpr[2]),
                inputs,
                "XSETBV must preserve EDX:EAX and ECX"
            );
            assert_eq!(regs.rflags & 0x8D5, flags & 0x8D5);
            regs
        };

        for (name, value, apx_enabled) in [
            ("x87", 1, false),
            ("x87+sse", 3, false),
            ("avx", 7, false),
            ("avx512", 0xE7, false),
            ("apx", 0x0008_00E7, true),
        ] {
            let regs = run(value, 1 << 18, 1, 0, apx_enabled, 0);
            assert_eq!(regs.xcr0, value, "{name}: committed XCR0");
            assert_eq!(regs.exit_pc, 0x1234_5003, "{name}: next PC handoff");
        }

        // CPL is ignored outside protected mode.
        let real_mode = run(7, 1 << 18, 0, 3, false, 0);
        assert_eq!(real_mode.xcr0, 7);
        assert_eq!(real_mode.exit_pc, 0x1234_5003);

        for (name, value, cr4, cr0, cpl, apx_enabled, selector) in [
            ("OSXSAVE clear", 7, 0, 1, 0, false, 0),
            ("protected CPL3", 7, 1 << 18, 1, 3, false, 0),
            ("selector one", 7, 1 << 18, 1, 0, false, 1),
            ("x87 disabled", 0, 1 << 18, 1, 0, false, 0),
            ("unsupported bit", 9, 1 << 18, 1, 0, false, 0),
            ("AVX without SSE", 5, 1 << 18, 1, 0, false, 0),
            ("partial AVX512", 0x27, 1 << 18, 1, 0, false, 0),
            ("AVX512 without AVX", 0xE3, 1 << 18, 1, 0, false, 0),
            ("APX disabled", 0x0008_0001, 1 << 18, 1, 0, false, 0),
            ("high unsupported", (1u64 << 63) | 1, 1 << 18, 1, 0, true, 0),
        ] {
            let regs = run(value, cr4, cr0, cpl, apx_enabled, selector);
            assert_eq!(regs.xcr0, 3, "{name}: XCR0 must not commit");
            assert_eq!(regs.exit_pc, 0x1234_5000, "{name}: fault restart PC");
        }
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_helper_backed_immediate_memory_bit_update_commits_cf_only_after_store() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        #[repr(C)]
        struct LoadResult {
            value: u64,
            ok: u64,
        }

        #[derive(Default)]
        struct MemoryContext {
            load_value: u64,
            store_value: u64,
            committed_value: u64,
            loads: u64,
            stores: u64,
            store_ok: u64,
        }

        extern "C" fn load(
            context: *mut MemoryContext,
            _addr: u64,
            _size: u64,
            _signed: u64,
        ) -> LoadResult {
            let context = unsafe { &mut *context };
            context.loads += 1;
            LoadResult {
                value: context.load_value,
                ok: 1,
            }
        }

        extern "C" fn store(
            context: *mut MemoryContext,
            _addr: u64,
            value: u64,
            _size: u64,
        ) -> u64 {
            let context = unsafe { &mut *context };
            context.stores += 1;
            context.store_value = value;
            if context.store_ok != 0 {
                context.committed_value = value;
            }
            context.store_ok
        }

        let old = VReg::Virtual(crate::smir::ir::types::VirtualId(35));
        let mask = VReg::Virtual(crate::smir::ir::types::VirtualId(36));
        let result = VReg::Virtual(crate::smir::ir::types::VirtualId(37));
        let address = Address::Absolute(0x4000);
        let mut builder = FunctionBuilder::new(FunctionId(0), 0x1000);
        builder.push_op(
            0x1000,
            OpKind::Load {
                dst: old,
                addr: address.clone(),
                width: MemWidth::B8,
                sign: SignExtend::Zero,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::Mov {
                dst: mask,
                src: SrcOperand::Imm(1),
                width: OpWidth::W64,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::Shl {
                dst: mask,
                src: mask,
                amount: SrcOperand::Imm(5),
                width: OpWidth::W64,
                flags: FlagUpdate::None,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::Not {
                dst: mask,
                src: mask,
                width: OpWidth::W64,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::And {
                dst: result,
                src1: old,
                src2: SrcOperand::Reg(mask),
                width: OpWidth::W64,
                flags: FlagUpdate::None,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::Store {
                src: result,
                addr: address,
                width: MemWidth::B8,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::Bt {
                src: old,
                index: SrcOperand::Imm(5),
                width: OpWidth::W64,
            },
        );
        builder.set_terminator(Terminator::Return { values: vec![] });

        let mut lowerer = X86_64Lowerer::new();
        lowerer.set_mem_helpers(true);
        let lowered = lowerer
            .lower_function(&builder.finish())
            .expect("lower helper-backed memory BTR");
        let exec = ExecMem::new(&lowerer.finalize().expect("finalize memory BTR"))
            .expect("map helper-backed memory BTR");

        const STATUS_MASK: u64 = 0x8D5;
        const INCOMING_FLAGS: u64 = 0x2 | 0x8D4; // CF clear
        let initial_gprs = {
            let mut gprs = [0u64; 32];
            for (index, value) in gprs.iter_mut().enumerate() {
                *value = 0xA500_0000_0000_0000 | index as u64;
            }
            gprs
        };

        let mut success_context = MemoryContext {
            load_value: 1 << 5,
            committed_value: 0xDEAD_BEEF_DEAD_BEEF,
            store_ok: 1,
            ..MemoryContext::default()
        };
        let mut success = GuestRegs::default();
        success.gpr = initial_gprs;
        success.rflags = INCOMING_FLAGS;
        success.exit_pc = 0xAAAA_BBBB_CCCC_DDDD;
        success.ctx = (&mut success_context as *mut MemoryContext) as u64;
        success.load_fn = load as usize as u64;
        success.store_fn = store as usize as u64;
        exec.run(lowered.entry_offset, &mut success);

        assert_eq!(success_context.loads, 1);
        assert_eq!(success_context.stores, 1);
        assert_eq!(success_context.store_value, 0, "BTR store value");
        assert_eq!(success_context.committed_value, 0);
        assert_eq!(success.gpr, initial_gprs, "success must preserve every GPR");
        assert_eq!(
            success.rflags & STATUS_MASK,
            (INCOMING_FLAGS & STATUS_MASK) | 1,
            "successful BTR must replace only CF"
        );
        assert_eq!(success.exit_pc, 0xAAAA_BBBB_CCCC_DDDD);

        let mut fault_context = MemoryContext {
            load_value: 1 << 5,
            committed_value: 0xDEAD_BEEF_DEAD_BEEF,
            store_ok: 0,
            ..MemoryContext::default()
        };
        let mut fault = GuestRegs::default();
        fault.gpr = initial_gprs;
        fault.rflags = INCOMING_FLAGS;
        fault.ctx = (&mut fault_context as *mut MemoryContext) as u64;
        fault.load_fn = load as usize as u64;
        fault.store_fn = store as usize as u64;
        exec.run(lowered.entry_offset, &mut fault);

        assert_eq!(fault_context.loads, 1);
        assert_eq!(fault_context.stores, 1);
        assert_eq!(fault_context.store_value, 0, "updated value reaches store");
        assert_eq!(
            fault_context.committed_value, 0xDEAD_BEEF_DEAD_BEEF,
            "failed store must not commit memory"
        );
        assert_eq!(fault.gpr, initial_gprs, "fault must preserve every GPR");
        assert_eq!(
            fault.rflags & STATUS_MASK,
            INCOMING_FLAGS & STATUS_MASK,
            "fault must preserve every arithmetic status flag"
        );
        assert_eq!(fault.exit_pc, 0x1000, "fault must restart current PC");
    }

    #[cfg(all(feature = "smir-jit", target_arch = "x86_64"))]
    #[test]
    fn native_helper_backed_memory_destination_alu_commits_flags_only_after_store() {
        use crate::smir::lower::runtime::{ExecMem, GuestRegs};

        #[repr(C)]
        struct LoadResult {
            value: u64,
            ok: u64,
        }

        #[derive(Default)]
        struct MemoryContext {
            load_value: u64,
            store_value: u64,
            committed_value: u64,
            last_addr: u64,
            last_size: u64,
            loads: u64,
            stores: u64,
            store_ok: u64,
        }

        extern "C" fn load(
            context: *mut MemoryContext,
            addr: u64,
            size: u64,
            _signed: u64,
        ) -> LoadResult {
            let context = unsafe { &mut *context };
            context.loads += 1;
            context.last_addr = addr;
            context.last_size = size;
            LoadResult {
                value: context.load_value,
                ok: 1,
            }
        }

        extern "C" fn store(context: *mut MemoryContext, addr: u64, value: u64, size: u64) -> u64 {
            let context = unsafe { &mut *context };
            context.stores += 1;
            context.last_addr = addr;
            context.last_size = size;
            context.store_value = value;
            if context.store_ok != 0 {
                context.committed_value = value;
            }
            context.store_ok
        }

        let old = VReg::Virtual(crate::smir::ir::types::VirtualId(40));
        let result = VReg::Virtual(crate::smir::ir::types::VirtualId(41));
        let flags_result = VReg::Virtual(crate::smir::ir::types::VirtualId(42));
        let source = VReg::Arch(ArchReg::X86(X86Reg::R16));
        let address = Address::Absolute(0x4000);
        let mut builder = FunctionBuilder::new(FunctionId(0), 0x1000);
        builder.push_op(
            0x1000,
            OpKind::Load {
                dst: old,
                addr: address.clone(),
                width: MemWidth::B8,
                sign: SignExtend::Zero,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::Add {
                dst: result,
                src1: old,
                src2: SrcOperand::Reg(source),
                width: OpWidth::W64,
                flags: FlagUpdate::None,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::Store {
                src: result,
                addr: address,
                width: MemWidth::B8,
            },
        );
        builder.push_op(
            0x1000,
            OpKind::Add {
                dst: flags_result,
                src1: old,
                src2: SrcOperand::Reg(source),
                width: OpWidth::W64,
                flags: FlagUpdate::All,
            },
        );
        builder.set_terminator(Terminator::Return { values: vec![] });

        let mut lowerer = X86_64Lowerer::new();
        lowerer.set_mem_helpers(true);
        let lowered = lowerer
            .lower_function(&builder.finish())
            .expect("lower helper-backed scalar RMW");
        let exec = ExecMem::new(&lowerer.finalize().expect("finalize scalar RMW"))
            .expect("map scalar RMW");

        const INCOMING_FLAGS: u64 = 0x2 | 0x8D5;
        let initial_gprs = {
            let mut gprs = [0u64; 32];
            for (index, value) in gprs.iter_mut().enumerate() {
                *value = 0xA500_0000_0000_0000 | index as u64;
            }
            gprs[16] = 1;
            gprs
        };

        let mut success_context = MemoryContext {
            load_value: u64::MAX,
            committed_value: 0xDEAD_BEEF_DEAD_BEEF,
            store_ok: 1,
            ..MemoryContext::default()
        };
        let mut success = GuestRegs::default();
        success.gpr = initial_gprs;
        success.rflags = INCOMING_FLAGS;
        success.exit_pc = 0xAAAA_BBBB_CCCC_DDDD;
        success.ctx = (&mut success_context as *mut MemoryContext) as u64;
        success.load_fn = load as usize as u64;
        success.store_fn = store as usize as u64;
        exec.run(lowered.entry_offset, &mut success);

        assert_eq!(success_context.loads, 1);
        assert_eq!(success_context.stores, 1);
        assert_eq!(success_context.last_addr, 0x4000);
        assert_eq!(success_context.last_size, 8);
        assert_eq!(success_context.store_value, 0);
        assert_eq!(success_context.committed_value, 0);
        assert_eq!(success.gpr, initial_gprs, "success must preserve every GPR");
        assert_eq!(success.rflags & 0x8D5, 0x55, "ADD result flags");
        assert_eq!(success.exit_pc, 0xAAAA_BBBB_CCCC_DDDD);

        let mut fault_context = MemoryContext {
            load_value: u64::MAX,
            committed_value: 0xDEAD_BEEF_DEAD_BEEF,
            store_ok: 0,
            ..MemoryContext::default()
        };
        let mut fault = GuestRegs::default();
        fault.gpr = initial_gprs;
        fault.rflags = INCOMING_FLAGS;
        fault.ctx = (&mut fault_context as *mut MemoryContext) as u64;
        fault.load_fn = load as usize as u64;
        fault.store_fn = store as usize as u64;
        exec.run(lowered.entry_offset, &mut fault);

        assert_eq!(fault_context.loads, 1);
        assert_eq!(fault_context.stores, 1);
        assert_eq!(fault_context.store_value, 0, "computed value reaches store");
        assert_eq!(
            fault_context.committed_value, 0xDEAD_BEEF_DEAD_BEEF,
            "failed store must not commit memory"
        );
        assert_eq!(fault.gpr, initial_gprs, "fault must preserve every GPR");
        assert_eq!(
            fault.rflags & 0x8D5,
            INCOMING_FLAGS & 0x8D5,
            "fault must preserve every arithmetic status flag"
        );
        assert_eq!(fault.exit_pc, 0x1000, "fault must restart current PC");
    }

